import 'dart:async'; import 'package:flutter_test/flutter_test.dart'; import 'package:http/http.dart' as http; import 'package:http/testing.dart'; import 'package:shared_preferences/shared_preferences.dart'; import 'package:hustle_mobile/features/analysis/data/analysis_repository.dart';
const valid='{"source_service":"hustle-analytics","source_event_id":"id","symbol":"BTCUSDT","exchange":"BINANCE","timeframe":"1h","action":"HOLD","confidence":0.2,"price":1,"signal_time":"2026-01-01T00:00:00Z","reasons":[],"indicators":{}}';
void main(){setUp(()=>SharedPreferences.setMockInitialValues({}));test('başarılı yanıt',()async{final repo=AnalysisRepository(baseUrl:'http://test',client:MockClient((_)async=>http.Response(valid,200)));expect((await repo.fetch('BTCUSDT','1h')).symbol,'BTCUSDT');});for(final code in [400,422,502]){test('$code hatasını kullanıcı mesajına çevirir',()async{final repo=AnalysisRepository(baseUrl:'http://test',client:MockClient((_)async=>http.Response('',code)));expect(()=>repo.fetch('BTCUSDT','1h'),throwsA(isA<AnalysisException>()));});}test('geçersiz JSON',()async{final repo=AnalysisRepository(baseUrl:'http://test',client:MockClient((_)async=>http.Response('{',200)));expect(()=>repo.fetch('BTCUSDT','1h'),throwsA(isA<AnalysisException>()));});test('timeout',()async{final repo=AnalysisRepository(baseUrl:'http://test',timeout:Duration.zero,client:MockClient((_)async{await Future<void>.delayed(const Duration(milliseconds:10));return http.Response(valid,200);}));expect(()=>repo.fetch('BTCUSDT','1h'),throwsA(isA<AnalysisException>()));});}
